-- Tool_Catalog registrations for the DataNeed flow (generated from the market-ai-orc tool definitions).
-- Inactive rows: market-ai-backend never lists them; market-ai-orc registers its tools in code, and only with
-- AI_ENABLE_DATANEED. The Analysis Spec tools it replaces get a dataneed_flow note; their rows are unchanged
-- otherwise, because switching the flag off restores them.
BEGIN;

DO $preflight$
BEGIN
    IF EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE (tool_name, version) IN (('submit_data_need_spec', 'v1'), ('prepare_data_bundle', 'v1'), ('open_analysis_session', 'v1'), ('run_python', 'v1'), ('inspect_session', 'v1'), ('get_session_output', 'v1'), ('complete_analysis', 'orc-v1'))) THEN
        RAISE EXCEPTION 'DataNeed tools are already registered';
    END IF;
END;
$preflight$;

UPDATE public."Tool_Catalog"
SET tool_specific_limits = tool_specific_limits || '{"dataneed_flow":"Not registered when AI_ENABLE_DATANEED is on: replaced by submit_data_need_spec (DataNeed flow)"}'::jsonb, updated_at = CURRENT_TIMESTAMP
WHERE tool_name = 'create_analysis_spec' AND tool_specific_limits->>'runtime_service' = 'market-ai-orc'
  AND version = (SELECT max(version) FROM public."Tool_Catalog" WHERE tool_name = 'create_analysis_spec'
                 AND tool_specific_limits->>'runtime_service' = 'market-ai-orc');

UPDATE public."Tool_Catalog"
SET tool_specific_limits = tool_specific_limits || '{"dataneed_flow":"Not registered when AI_ENABLE_DATANEED is on: replaced by prepare_data_bundle (DataNeed flow)"}'::jsonb, updated_at = CURRENT_TIMESTAMP
WHERE tool_name = 'prepare_analysis_data' AND tool_specific_limits->>'runtime_service' = 'market-ai-orc'
  AND version = (SELECT max(version) FROM public."Tool_Catalog" WHERE tool_name = 'prepare_analysis_data'
                 AND tool_specific_limits->>'runtime_service' = 'market-ai-orc');

UPDATE public."Tool_Catalog"
SET tool_specific_limits = tool_specific_limits || '{"dataneed_flow":"Not registered when AI_ENABLE_DATANEED is on: replaced by open_analysis_session and run_python (DataNeed flow)"}'::jsonb, updated_at = CURRENT_TIMESTAMP
WHERE tool_name = 'run_python_analysis' AND tool_specific_limits->>'runtime_service' = 'market-ai-orc'
  AND version = (SELECT max(version) FROM public."Tool_Catalog" WHERE tool_name = 'run_python_analysis'
                 AND tool_specific_limits->>'runtime_service' = 'market-ai-orc');

UPDATE public."Tool_Catalog"
SET tool_specific_limits = tool_specific_limits || '{"dataneed_flow":"Not registered when AI_ENABLE_DATANEED is on: replaced by complete_analysis (DataNeed flow)"}'::jsonb, updated_at = CURRENT_TIMESTAMP
WHERE tool_name = 'get_analysis_result' AND tool_specific_limits->>'runtime_service' = 'market-ai-orc'
  AND version = (SELECT max(version) FROM public."Tool_Catalog" WHERE tool_name = 'get_analysis_result'
                 AND tool_specific_limits->>'runtime_service' = 'market-ai-orc');

UPDATE public."Tool_Catalog"
SET tool_specific_limits = tool_specific_limits || '{"dataneed_flow":"Not registered when AI_ENABLE_DATANEED is on: replaced by prepare_data_bundle (DataNeed flow)"}'::jsonb, updated_at = CURRENT_TIMESTAMP
WHERE tool_name = 'get_dataset_manifest' AND tool_specific_limits->>'runtime_service' = 'market-ai-orc'
  AND version = (SELECT max(version) FROM public."Tool_Catalog" WHERE tool_name = 'get_dataset_manifest'
                 AND tool_specific_limits->>'runtime_service' = 'market-ai-orc');

INSERT INTO public."Tool_Catalog" (
    tool_name, tool_family, tool_type, purpose, input_schema, output_schema,
    execution_type, handler_name, default_output_rows, max_output_rows,
    max_input_rows, max_tickers, max_date_range_days, max_estimated_rows,
    timeout_seconds, max_output_bytes, max_llm_result_rows,
    max_llm_result_bytes, max_llm_result_tokens,
    requires_analytics_worker, requires_feature_catalog, requires_data_readiness,
    tool_specific_limits, version, is_active
)
VALUES
    ('submit_data_need_spec', 'ADVANCED', 'VALIDATION', 'Declare which data the answer needs (DataNeedSpec), before any extraction. It lists logical data requests and catalog relationships only: never a formula, indicator, method, ranking or output; all calculations are written later in the analysis session. Each data request names one catalog table, the columns needed, a scope (expression tree on filterable columns of that table: ALL, PREDICATE, AND/OR with children, NOT with child), one or more named time ranges (e.g. the current YTD and the same period last year), the source frequency and the analysis frequency (resample when coarser), history_buffer for warm-up observations before each range and future_buffer for observations after it, and ordering. Copy table names, entity/time columns, frequencies and subject from discover_catalog and get_catalog_details, and relationship ids and join semantics from the catalog relationships. A restriction by another table (for example prices of banks only) is a second data request on the reference table with its own scope, joined by an INNER relationship; never a manual ticker list. The validator answers APPROVED (need_id; next: prepare the data bundle), REVISION_REQUIRED (issues with data_request_id, code, field_path and rejected_value; fix each and resubmit with revision + 1, same request_group_id and data_request_ids), or CATALOG_UNAVAILABLE (stop and report temporarily). It never suggests a replacement: read the catalog again instead of guessing. mode RESEARCH also needs research_governance (hypothesis, candidate_count, pairwise_comparisons, multiple_testing_policy, optional holdout range and minimum sample); the Research Governor answers APPROVED, REPLAN_REQUIRED or REJECTED with a reason code. The same revision sent again returns the same answer.', '{"additionalProperties":false,"properties":{"data_requests":{"description":"1-8 logical data requests.","items":{"additionalProperties":false,"properties":{"analysis_frequency":{"description":"Frequency of the analysis (same as source, or coarser with resample).","type":"string"},"columns":{"description":"Catalog columns needed (entity and time columns are always added).","items":{"type":"string"},"type":"array"},"data_request_id":{"description":"<request_group_id>_<suffix>, suffix 1-12 letters/digits, e.g. data_request_1_A. Stable across revisions.","type":"string"},"entity_column":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"The table''s catalog entity_column; null when it has none."},"future_buffer":{"anyOf":[{"additionalProperties":false,"properties":{"unit":{"enum":["TRADING_OBSERVATIONS","CALENDAR_DAYS"],"type":"string"},"value":{"type":"integer"}},"required":["value","unit"],"type":"object"},{"type":"null"}],"description":"Observations after each range (e.g. forward outcomes); null if none."},"history_buffer":{"anyOf":[{"additionalProperties":false,"properties":{"unit":{"enum":["TRADING_OBSERVATIONS","CALENDAR_DAYS"],"type":"string"},"value":{"type":"integer"}},"required":["value","unit"],"type":"object"},{"type":"null"}],"description":"Observations before each range needed as warm-up; null if none."},"logical_name":{"description":"Lower-case name the session loads the data by, e.g. prices.","type":"string"},"ordering":{"description":"Row order of the delivered dataset ([] for none).","items":{"additionalProperties":false,"properties":{"column":{"type":"string"},"direction":{"enum":["ASC","DESC"],"type":"string"}},"required":["column","direction"],"type":"object"},"type":"array"},"resample":{"anyOf":[{"enum":["DAILY","WEEKLY","MONTHLY","QUARTERLY","YEARLY"],"type":"string"},{"type":"null"}],"description":"Required when analysis_frequency is coarser than source_frequency; else null."},"sampling_allowed":{"description":"Always false: data is never sampled.","type":"boolean"},"scope":{"additionalProperties":false,"description":"Which rows, as an expression tree on filterable columns of this table.","properties":{"chi