umns","scope","time_ranges","source_frequency","analysis_frequency","resample","history_buffer","future_buffer","ordering","sampling_allowed"],"type":"object"},"type":"array"},"mode":{"enum":["ANALYSIS","RESEARCH"],"type":"string"},"question":{"description":"The user''s question, restated.","type":"string"},"relationships":{"description":"Catalog relationships between requests ([] for none).","items":{"additionalProperties":false,"properties":{"as_of_direction":{"anyOf":[{"enum":["BACKWARD"],"type":"string"},{"type":"null"}],"description":"AS_OF only; else null."},"effective_from_column":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"EFFECTIVE_DATED only: catalog column; else null."},"effective_to_column":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"EFFECTIVE_DATED only: catalog column; else null."},"join_semantics":{"description":"One of the relationship''s supported_join_semantics in the catalog.","enum":["CURRENT_STATE","EXACT_DATE","AS_OF","EFFECTIVE_DATED"],"type":"string"},"join_type":{"description":"INNER restricts the left request to rows with a match in the right request''s scope; LEFT leaves it unrestricted. Each request is delivered as its own dataset; the analysis joins them.","enum":["INNER","LEFT"],"type":"string"},"left_column":{"type":"string"},"left_request_id":{"type":"string"},"left_time_column":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"EXACT_DATE / AS_OF: the catalog left time column; else null."},"relationship_id":{"description":"Catalog relationship_id between the two requests'' tables.","type":"integer"},"right_column":{"type":"string"},"right_request_id":{"type":"string"},"right_time_column":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"EXACT_DATE / AS_OF: the catalog right time column; else null."}},"required":["relationship_id","left_request_id","left_column","right_request_id","right_column","join_type","join_semantics","left_time_column","right_time_column","as_of_direction","effective_from_column","effective_to_column"],"type":"object"},"type":"array"},"request_group_id":{"description":"Lower-case id of this data need, e.g. data_request_1; revisions keep it.","type":"string"},"research_governance":{"anyOf":[{"additionalProperties":false,"properties":{"candidate_count":{"description":"Conditions, lags or parameter combinations the experiment evaluates.","type":"integer"},"followup_of":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"request_group_id of an approved experiment on the same hypothesis this one follows up; else null."},"holdout":{"anyOf":[{"additionalProperties":false,"properties":{"data_request_id":{"type":"string"},"range_id":{"description":"One of that request''s declared ranges, kept out of fitting.","type":"string"}},"required":["data_request_id","range_id"],"type":"object"},{"type":"null"}]},"hypothesis":{"type":"string"},"hypothesis_id":{"description":"Lower-case id; revisions of a request group keep it.","type":"string"},"minimum_sample":{"anyOf":[{"additionalProperties":false,"properties":{"unit":{"enum":["EVENTS","OBSERVATIONS","ENTITIES"],"type":"string"},"value":{"type":"integer"}},"required":["value","unit"],"type":"object"},{"type":"null"}]},"multiple_testing_policy":{"description":"NONE only for a single comparison.","enum":["NONE","BONFERRONI","HOLM","BENJAMINI_HOCHBERG"],"type":"string"},"objective":{"type":"string"},"pairwise_comparisons":{"type":"integer"}},"required":["hypothesis_id","hypothesis","objective","candidate_count","pairwise_comparisons","holdout","minimum_sample","multiple_testing_policy","followup_of"],"type":"object"},{"type":"null"}],"description":"Required for RESEARCH; null for ANALYSIS."},"revision":{"description":"1 for the first submission, then the next number for each revision.","type":"integer"},"spec_version":{"enum":["data_need_spec/v1"],"type":"string"},"subject":{"additionalProperties":false,"properties":{"asset_type":{"anyOf":[{"type":"string"},{"type":"null"}]},"data_domain":{"type":"string"},"entity_type":{"type":"string"}},"required":["data_domain","entity_type","asset_type"],"type":"object"}},"required":["spec_version","request_group_id","revision","mode","question","subject","data_requests","relationships","research_governance"],"type":"object"}'::jsonb, '{"description":"The DataNeedValidator result (model view): APPROVED with need_id, REVISION_REQUIRED with issues {data_request_id, code, field_path, rejected_value}, or CATALOG_UNAVAILABLE; the Research Governor decision.","properties":{"issues":{},"message":{},"need_id":{},"next_action":{},"replayed":{},"research_governance":{},"revision":{},"status":{},"warnings":{}},"type":"object"}'::jsonb,
     'ORCHESTRATOR', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 20000, 200, 20000, NULL,
     false, false, false, '{"executor_service":"market-python-sandbox","feature_flag":"AI_ENABLE_DATANEED","forbidden_content":["formulas","indicators","methods","rankings","outputs"],"handler":"app/tools/data_need.py","inner_relationship":"restricts both requests by the other request''s own scope (semi-join pushdown); the exact join runs in the analysis session","join_semantics":["CURRENT_STATE","EXACT_DATE","AS_OF","EFFECTIVE_DATED"],"join_semantics_source":"AI_catalog_relationships.supported_join_semantics (migration 20260925_003)","max_scope_depth":4,"modes":["ANALYSIS","RESEARCH"],"registry_state":"Registered in market-ai-orc only with AI_ENABLE_DATANEED; is_active=false keeps it out of market-ai-backend tool lists.","revision_rules":"revision + 1 per resubmission; a catalog outage or REVISION_CONFLICT uses no revision","runtime_commit":"daa05cc","runtime_service":"market-ai-orc","sandbox_endpoint":"POST /v1/data-needs","sandbox_flag":"PY_SANDBOX_DATANEED_ENABLED","server_supplied_fields":["request_id","reference_time","timezone"],"spec_version":"data_need_spec/v1","statuses":["APPROVED","REVISION_REQUIRED","CATALOG_UNAVAILABLE"],"validator_layers":["schema","catalog_binding","cross_request","planning_feasibility"]}'::jsonb, 'v1', false),
    ('prepare_data_bundle', 'ADVANCED', 'RETRIEVAL', 'Extract and deliver the data of an APPROVED DataNeedSpec as one governed data bundle. The backend plans the physical extractions (column pruning, scope and join pushdown, merged or separate range windows, date or entity partitions) and the SQL Governor checks and extracts each part; nothing is sampled, truncated or re-scoped. The sandbox verifies every part, profiles the data and checks coverage. Returns READY with input_bundle_id and, per data request, rows, entities, first/last date, each requested range with its actual bounds and status (OK, PARTIAL, EMPTY), quality_flags (e.g. NULL_VALUES, FREQUENCY_GAPS, HISTORY_BUFFER_SHORTFALL, EMPTY_ENTITY, DUPLICATE_KEYS) and relationship warnings; or REJECTED naming the data_request_id, the reason code and the next action. Quality flags are facts about the data to investigate and disclose, not failures. Never change the user''s scope to pass a limit: revise the DataNeedSpec only when the rejection says so.', '{"additionalProperties":false,"properties":{"need_id":{"description":"need_id of an APPROVED DataNeedSpec.","type":"string"}},"required":["need_id"],"type":"object"}'::jsonb, '{"description":"READY with input_bundle_id and per-request rows, entities, ranges, quality flags and relationship warnings; or REJECTED naming the data_request_id, the Governor status, the code and the next action.","properties":{"datasets":{},"decisions":{},"input_bundle_id":{},"need_id":{},"next_action":{},"plan":{},"rejection":{},"relationship_warnings":{},"replayed":{},"status":{}},"type":"object"}'::jsonb,
     'ORCHESTRATOR', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 40000, 200, 40000, NULL,
     false, false, false, '{"bundle_checks":["lineage","executed_scope","catalog_hash","partition_tiling","row_count","entities_sha256","data_quality_profile"],"decisions":["COLUMN_PRUNING","PREDICATE_PUSHDOWN","SEMI_JOIN_PUSHDOWN","RANGE_MERGE","DATE_PARTITION","ENTITY_PARTITION","RESAMPLE_IN_SESSION"],"executor_service":"market-python-sandbox","feature_flag":"AI_ENABLE_DATANEED","governor_endpoint":"POST /v1/extract (orc key)","governor_statuses":["APPROVED","APPROVED_WITH_PARTITIONING","REJECTED_POLICY","REJECTED_SCAN_SIZE","REJECTED_ROW_LIMIT","REJECTED_COMPUTE_COST","REJECTED_JOIN_COST","REJECTED_TIMEOUT_RISK"],"handler":"app/tools/data_planner.py (ExecutionPlanner)","max_parts_per_request":64,"never":["sampling","truncation","narrowing the scope","shortening a range"],"registry_state":"Registered in market-ai-orc only with AI_ENABLE_DATANEED; is_active=false keeps it out of market-ai-backend tool lists.","runtime_commit":"daa05cc","runtime_service":"market-ai-orc","sandbox_endpoint":"POST /v1/bundles","sandbox_flag":"PY_SANDBOX_DATANEED_ENABLED"}'::jsonb, 'v1', false),
    ('open_analysis_session', 'ADVANCED', 'COMPUTATION', 'Open a persistent Python analysis session on a READY governed bundle (input_bundle_id from prepare_data_bundle). Returns session_id, the datasets (data_request_id, logical name, columns, rows, ranges, quality flags), the relationships with their join semantics, the helper functions and the limits. Variables and functions persist across run_python calls until the session closes (idle timeout, limits, or a restart of the sandbox: then open a new session on the same bundle).', '{"additionalProperties":false,"properties":{"input_bundle_id":{"description":"input_bundle_id of a READY bundle.","type":"string"}},"required":["input_bundle_id"],"type":"object"}'::jsonb, '{"description":"The session: session_id, datasets, relationships with their join semantics, helpers and limits.","properties":{"bundle_id":{},"datasets":{},"helpers":{},"limits":{},"need_id":{},"relationships":{},"session_id":{},"status":{}},"type":"object"}'::jsonb,
     'ORCHESTRATOR', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 40000, 200, 40000, NULL,
     false, false, false, '{"executor_service":"market-python-sandbox","feature_flag":"AI_ENABLE_DATANEED","handler":"app/tools/session.py","isolation":"one confined worker process per session (dedicated uid, seccomp, no network, no database)","lifetime":"bound to the request; closed on idle, limits, completion or a sandbox restart","registry_state":"Registered in market-ai-orc only with AI_ENABLE_DATANEED; is_active=false keeps it out of market-ai-backend tool lists.","runtime_commit":"daa05cc","runtime_service":"market-ai-orc","sandbox_endpoint":"POST /v1/sessions","sandbox_flag":"PY_SANDBOX_DATANEED_ENABLED"}'::jsonb, 'v1', false),
    ('run_python', 'ADVANCED', 'COMPUTATION', 'Run Python in the session. pandas as pd, numpy as np and saniti with all its helpers are pre-bound; TA-Lib (import talib), scipy, statsmodels, polars, duckdb and matplotlib are available. Read data only through the helpers: load(request) returns a whole dataset (every row of every range, including warm-up history), range(request, range_id, include_buffers=False) one approved range, sql(query) DuckDB over one view per logical name, join(relationship_id) the approved relationship with its point-in-time semantics, quality(request) the Data Quality Manifest, requests() and manifest() the bundle, resample(frame, request) the catalog rules. Reads outside the helpers count as not processed. Write any logic you need; define functions and call them later. Emit results with emit_table(name, frame), emit_json(name, value), emit_text(name, text), emit_chart(figure, name, title), emit_file(name, data, format); each returns output metadata and the tool result lists output_ids. print() is diagnostics only. Results: OK; SCRIPT_ERROR with error_type, line, field (e.g. a missing column) and traceback: fix the code and rerun (earlier variables remain); TIMEOUT (the execution was interrupted, the session remains); INSUFFICIENT_INPUT_DATA after saniti.insufficient_data(request, range_id, value, unit, reason): revise the DataNeedSpec (for example more history). No network, database, subprocess or writes outside intermediate_path(name).', '{"additionalProperties":false,"properties":{"code":{"description":"Python to run in the session''s namespace.","type":"string"},"session_id":{"type":"string"}},"required":["session_id","code"],"type":"object"}'::jsonb, '{"description":"One execution: OK, SCRIPT_ERROR (error_type, line, field, traceback), TIMEOUT or INSUFFICIENT_INPUT_DATA, with bounded stdout, outputs and changed variables.","properties":{"budgets":{},"error":{},"execution_id":{},"insufficient_data":{},"outputs":{},"session_id":{},"status":{},"stdout":{},"variables":{}},"type":"object"}'::jsonb,
     'ORCHESTRATOR', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 40000, 200, 40000, NULL,
