    ('inspect_session', 'ADVANCED', 'COMPUTATION', 'Describe session variables: with names null, every variable (name, type, shape); with names, up to 20 variables with dtypes and up to max_rows preview rows. Use it to check intermediate results before emitting outputs.', '{"additionalProperties":false,"properties":{"max_rows":{"anyOf":[{"type":"integer"},{"type":"null"}],"description":"Preview rows per DataFrame (default 5)."},"names":{"anyOf":[{"items":{"type":"string"},"type":"array"},{"type":"null"}],"description":"Variables to describe with a preview; null lists every variable (names, types, shapes)."},"session_id":{"type":"string"}},"required":["session_id","names","max_rows"],"type":"object"}'::jsonb, '{"description":"Variable descriptions (name, type, shape, dtypes) with bounded previews.","properties":{"session_id":{},"truncated":{},"variables":{}},"type":"object"}'::jsonb,
     'ORCHESTRATOR', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 40000, 200, 40000, NULL,
     false, false, false, '{"executor_service":"market-python-sandbox","feature_flag":"AI_ENABLE_DATANEED","handler":"app/tools/session.py","max_names":20,"max_preview_rows":20,"registry_state":"Registered in market-ai-orc only with AI_ENABLE_DATANEED; is_active=false keeps it out of market-ai-backend tool lists.","runtime_commit":"daa05cc","runtime_service":"market-ai-orc","sandbox_endpoint":"POST /v1/sessions/{session_id}/inspect","sandbox_flag":"PY_SANDBOX_DATANEED_ENABLED"}'::jsonb, 'v1', false),
    ('get_session_output', 'ADVANCED', 'RETRIEVAL', 'Read back one output of the session: table rows page by page (offset, limit), JSON content or text chunks; charts and files return metadata only. released is false until complete_analysis passes: only released outputs may be cited in the final answer.', '{"additionalProperties":false,"properties":{"limit":{"anyOf":[{"type":"integer"},{"type":"null"}],"description":"Rows (tables) or chunks (text) to return; default 50."},"offset":{"anyOf":[{"type":"integer"},{"type":"null"}],"description":"First row (tables) or chunk (text); default 0."},"output_id":{"type":"string"},"session_id":{"type":"string"}},"required":["session_id","output_id","offset","limit"],"type":"object"}'::jsonb, '{"description":"One session output: table rows page by page, JSON or text chunks, or metadata for charts and files; released is true only after complete_analysis passed.","properties":{"checksum_sha256":{},"columns":{},"content":{},"format":{},"name":{},"next_offset":{},"offset":{},"output_id":{},"released":{},"row_count":{},"rows":{},"type":{}},"type":"object"}'::jsonb,
     'ORCHESTRATOR', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 40000, 200, 40000, NULL,
     false, false, false, '{"citation_rule":"only released outputs may be cited in an answer","executor_service":"market-python-sandbox","feature_flag":"AI_ENABLE_DATANEED","handler":"app/tools/session.py","max_rows_per_page":200,"registry_state":"Registered in market-ai-orc only with AI_ENABLE_DATANEED; is_active=false keeps it out of market-ai-backend tool lists.","runtime_commit":"daa05cc","runtime_service":"market-ai-orc","sandbox_endpoint":"GET /v1/sessions/{session_id}/outputs/{output_id}","sandbox_flag":"PY_SANDBOX_DATANEED_ENABLED"}'::jsonb, 'v1', false),
    ('complete_analysis', 'ADVANCED', 'VALIDATION', 'Finish the analysis of a session. The backend builds the ExecutionManifest and runs the Coverage Validator: every approved data request and range must have been delivered as approved and read in full through the saniti helpers in a successful execution, with at least one output. Returns final_status (data_coverage PASS/FAIL, sandbox_execution, calculation_validation NOT_PERFORMED, evidence_label, warnings, claims_allowed, claims_forbidden) and, on PASS, the released outputs with their content (JSON outputs and the first table rows). Only released outputs may be cited in the answer; disclose the warnings. On FAIL follow next_action: RUN_PYTHON (read what was not processed, then complete again), REVISE_DATA_NEED_SPEC, or REPORT_LIMITATION. The backend does not recalculate your formulas: never say a calculation was independently verified.', '{"additionalProperties":false,"properties":{"session_id":{"type":"string"}},"required":["session_id"],"type":"object"}'::jsonb, '{"description":"The ExecutionManifest check and the final status; on PASS the released outputs and their content.","properties":{"completion_id":{},"coverage":{},"final_status":{},"message":{},"need_id":{},"next_action":{},"released_contents":{},"released_outputs":{},"replayed":{},"session_id":{},"status":{}},"type":"object"}'::jsonb,
     'ORCHESTRATOR', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 40000, 200, 40000, NULL,
     false, false, false, '{"calculation_validation":"NOT_PERFORMED: the backend verifies data coverage, never the formulas","evidence_labels":["DATA_COVERAGE_VERIFIED","NOT_VALIDATED"],"executor_service":"market-python-sandbox","feature_flag":"AI_ENABLE_DATANEED","final_status_fields":["data_need_validation","research_governance","sql_governance","data_quality_profiling","data_coverage","sandbox_execution","calculation_validation","data_complete","execution_complete","evidence_label","warnings","claims_allowed","claims_forbidden","research_constraints"],"handler":"app/tools/session.py","name_note":"market-ai-backend''s retired complete_analysis v1 is a different tool with the same name; this row is versioned orc-v1 so both rows stay intact","next_actions":["ANSWER_FROM_RELEASED_OUTPUTS","RUN_PYTHON","REVISE_DATA_NEED_SPEC","REPORT_LIMITATION"],"registry_state":"Registered in market-ai-orc only with AI_ENABLE_DATANEED; is_active=false keeps it out of market-ai-backend tool lists.","released_preview":{"max_outputs":10,"max_rows":200},"runtime_commit":"daa05cc","runtime_service":"market-ai-orc","sandbox_endpoint":"POST /v1/sessions/{session_id}/complete","sandbox_flag":"PY_SANDBOX_DATANEED_ENABLED"}'::jsonb, 'orc-v1', false);

DO $verify$
BEGIN
    IF (SELECT count(*) FROM public."Tool_Catalog" WHERE tool_specific_limits->>'runtime_service' = 'market-ai-orc'
          AND NOT is_active AND (tool_name, version) IN (('submit_data_need_spec', 'v1'), ('prepare_data_bundle', 'v1'), ('open_analysis_session', 'v1'), ('run_python', 'v1'), ('inspect_session', 'v1'), ('get_session_output', 'v1'), ('complete_analysis', 'orc-v1'))) <> 7 THEN
        RAISE EXCEPTION 'Expected 7 inactive DataNeed tool registrations';
    END IF;
    IF (SELECT count(*) FROM public."Tool_Catalog" WHERE tool_specific_limits->>'runtime_service' = 'market-ai-orc'
          AND tool_specific_limits->>'dataneed_flow' LIKE 'Not registered when AI_ENABLE_DATANEED%') <> 5 THEN
        RAISE EXCEPTION 'Expected the 5 replaced Analysis Spec tools to carry the DataNeed note';
    END IF;
END;
$verify$;

COMMIT;
